  audioCtx=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000});
  // ⚠️ المؤتمرات: نعطل كتم ضجيج المتصفح — يعتبر صوت مكبر القاعة "ضجيجاً" فيمحو كلام المتحدث!
  // التنظيف كله في الخادم (AGC + highpass + noise gate). autoGainControl أيضاً يفسد قياساتنا.
  // 🔊 الصوت الخافت من هواتف معينة: نستخدم إعدادات المتصفح الافتراضية كاملة
  // (معطّلات الضبط كانت تخنق الميكروفون في بعض أجهزة أندرويد → صوت شبه ميت)
  // + نضاعف مستوى الصوت ×3 في المتصفح قبل الإرسال مباشرة:
  try{
    stream=await navigator.mediaDevices.getUserMedia({audio:true});
  }catch(err){
    status("❌ الميكروفون مرفوض — اضغط 🔒 أعلى المتصفح واسمح بالميكروفون");
    running=false; $("#goBtn").disabled=false;
    return;
  }
  const gainNode=audioCtx.createGain();
  gainNode.gain.value=3.0;  // تضخيم مبدئي في المتصفح — AGC الخادم يكمل الباقي
  // إبقاء الصوت حياً حتى لو صغّر المتصفح (أندرويد يوقف الكapture عند إخفاء الصفحة)
  audioCtx.onstatechange=()=>{ if(audioCtx.state==="suspended") audioCtx.resume(); };
  const srcNode=audioCtx.createMediaStreamSource(stream);
  proc=audioCtx.createScriptProcessor(4096,1,1);
  // مؤشر مستوى الصوت
  const analyser=audioCtx.createAnalyser();
  gainNode.connect(analyser);   // نقيس بعد التضخيم ×3 (الصوت الفعلي الذي يُرسل للخادم)
  const buf=new Uint8Array(analyser.frequencyBinCount);
  let lastLvlBand=-1;
  setInterval(()=>{
    if(!running) return;
    analyser.getByteTimeDomainData(buf);
    let peak=0;
    for(const v of buf) peak=Math.max(peak,Math.abs(v-128));
    const lvl=(peak/128)*100;
    $("#meterFill").style.width=Math.min(100,lvl)+"%";
    // مؤشر حالة واضح بلا وميض مزعج: يتغير فقط عند تغير النطاق
    const band = lvl<4 ? 0 : lvl<10 ? 1 : 2;
    if(band!==lastLvlBand){
      lastLvlBand=band;
      if(band===0) status("🔇 لا يصلنا صوت — تأكد أن الميكروفون يلتقط");
      else if(band===1) status("🟡 صوت خفيف — الاقتراب من السماعة يحسّن الالتقاط");
      else if(!lastStatusLock) status("🟢 الصوت ممتاز — الترجمة تعمل");
    }
  },600);
  srcNode.connect(gainNode);
  gainNode.connect(proc);
  proc.connect(audioCtx.destination);
  proc.onaudioprocess=e=>{
    if(!ws||ws.readyState!==1) return;
    const pcm=e.inputBuffer.getChannelData(0);
    // float32 → int16
    const i16=new Int16Array(pcm.length);
    for(let i=0;i<pcm.length;i++){
      const s=Math.max(-1,Math.min(1,pcm[i]));
      i16[i]=s<0?s*0x8000:s*0x7FFF;
    }
    ws.send(i16.buffer);
    lastSend=Date.now();
  };
  // نبض صامت يمنع وسطاء الشبكة من قطع الاتصال الخامل
  setInterval(()=>{
    if(ws&&ws.readyState===1&&Date.now()-lastSend>8000){
      ws.send(new Int16Array(1600).buffer); // 100ms صمت
      lastSend=Date.now();
    }
  },9000);
};
